// All numbers on /benchmark come from data/benchmark.json (generated by ContextBridge-Benchmark/merge.py).
import raw from "../data/benchmark.json";
/* eslint-disable @typescript-eslint/no-explicit-any */
export const B: any = raw;
export const v1 = B.v1, v2 = B.v2, before = B.before;
export const ms = (s: number) => `${Math.round(s * 1000)} ms`;
export const num = (n: number) => n.toLocaleString("en-US");
export const pct = (x: number, d = 1) => `${(x * 100).toFixed(d)}%`;
export const allScenarios: any[] = [...v1.drift, ...v2.scenarios_ext];
export const scenarioPass = allScenarios.filter((s) => s.verdict_ok).length;
export const speedTop = v1.speed.rows[v1.speed.rows.length - 1];
export const families = (() => {
  const m: Record<string, { pass: number; total: number }> = {};
  for (const s of allScenarios) { const f = s.family || s.category; (m[f] ||= { pass: 0, total: 0 }).total++; if (s.verdict_ok) m[f].pass++; }
  return Object.entries(m).sort((a, b) => b[1].total - a[1].total);
})();
